"""Validation rules migrated from Meridian CRM 4.2 account_rules.vrl."""

from decimal import Decimal
from typing import Any


def _value(row: dict | None, column: str) -> Any:
    """Return a column value, treating missing values as an empty string."""
    if row is None:
        return ""
    value = row.get(column, "")
    return "" if value is None else value


def _length(value: Any) -> int:
    """Implement VRL LEN semantics."""
    if value is None:
        return 0
    return len(str(value))


def _nvl(value: Any, default: Any) -> Any:
    """Implement VRL NVL semantics."""
    return default if value is None or value == "" else value


def _number(value: Any) -> Decimal:
    """Coerce a NUMBER value using VRL empty-to-zero semantics."""
    if value is None or value == "":
        return Decimal(0)
    return Decimal(str(value))


def validate(
    record: dict,
    old: dict | None = None,
    event: str = "INSERT",
    today: str = "20260901",
) -> list[dict]:
    """Evaluate applicable account validation rules in legacy file order."""
    del today  # Part of the fixed interface; unused by these rules.

    errors: list[dict] = []

    if event in ("INSERT", "UPDATE"):
        # ACC-001
        if not (_length(_value(record, "ACCT_NM")) >= 2):
            errors.append(
                {
                    "code": "E1001",
                    "message": "Account name too short",
                    "severity": "BLOCK",
                }
            )

        # ACC-002
        account_type = _value(record, "ACCT_TYP")
        if not (
            account_type == "C"
            or account_type == "P"
            or account_type == "R"
            or account_type == "X"
        ):
            errors.append(
                {
                    "code": "E1002",
                    "message": "Invalid account type",
                    "severity": "BLOCK",
                }
            )

        # ACC-003
        annual_revenue = _nvl(_value(record, "ANN_REV"), 0)
        if not (_number(annual_revenue) >= 0):
            errors.append(
                {
                    "code": "E1003",
                    "message": "Annual revenue negative",
                    "severity": "BLOCK",
                }
            )

    # ACC-004
    if event == "UPDATE":
        old_credit_hold = _value(old, "CRED_HOLD")
        new_credit_hold = _value(record, "CRED_HOLD")
        credit_limit = _number(_value(record, "CRED_LIMIT"))

        if (
            old_credit_hold == "Y"
            and new_credit_hold == "N"
            and credit_limit <= 0
        ):
            errors.append(
                {
                    "code": "E1004",
                    "message": "Cannot release credit hold with zero credit limit",
                    "severity": "BLOCK",
                }
            )

    if event in ("INSERT", "UPDATE"):
        # ACC-005
        if not (_length(_value(record, "REGION_CD")) == 3):
            errors.append(
                {
                    "code": "E1005",
                    "message": "Region code must be 3 chars",
                    "severity": "WARN",
                }
            )

    return errors


def is_blocked(errors: list[dict]) -> bool:
    """Return whether any validation failure blocks the write."""
    return any(error.get("severity") == "BLOCK" for error in errors)
